package com.bautruc.ecommerce.payment.infrastructure;
import java.util.*;import com.bautruc.ecommerce.payment.domain.Payment;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface PaymentJpaRepository extends JpaRepository<Payment,Long>{Optional<Payment> findByOrderId(Long orderId);Optional<Payment> findByExternalTransactionIdentifier(String reference);List<Payment> findByOrderIdIn(Collection<Long> orderIds);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from Payment p where p.id=:id")Optional<Payment> findByIdForUpdate(@Param("id")Long id);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select p from Payment p where p.orderId=:orderId")Optional<Payment> findByOrderIdForUpdate(@Param("orderId")Long orderId);@Query(value="select id from payments where status='PENDING' and expires_at<=:now order by expires_at limit :limit",nativeQuery=true)List<Long> findExpiredCandidateIds(@Param("now")java.time.Instant now,@Param("limit")int limit);}
